<?php require_once __DIR__.'/includes/functions.php';logged();$r=$_SESSION['role'];$page_title='Dashboard';include __DIR__.'/includes/header.php';?><h1>Hello, <?=e($_SESSION['name'])?>!</h1><p class="muted">Welcome to your Sunog Kilay EMC learning space.</p>
<?php if($r==='admin'):?><div class="card"><h2>Administration</h2><p>Create accounts, view professors, manage courses and users, and enroll students in courses.</p><a class="btn" href="<?=BASE_URL?>/admin/courses.php">Manage courses</a> <a class="btn soft" href="<?=BASE_URL?>/admin/professors.php">Professors</a> <a class="btn soft" href="<?=BASE_URL?>/admin/users.php">Manage users</a> <a class="btn soft" href="<?=BASE_URL?>/admin/enroll.php">Enroll students</a></div><?php elseif($r==='teacher'): $due=$conn->prepare('SELECT a.title,a.due_date,c.subject_code,c.title course_title FROM assignments a JOIN courses c ON c.id=a.course_id JOIN users u ON u.id=? LEFT JOIN professors p ON p.id=c.professor_id WHERE (c.teacher_id=u.id OR p.email=u.email) AND a.due_date IS NOT NULL AND a.due_date>=NOW() ORDER BY a.due_date LIMIT 5');$due->bind_param('i',$_SESSION['user_id']);$due->execute();$deadlines=$due->get_result();?><div class="card"><h2>My Courses</h2><p class="muted">Courses assigned to you by the administrator.</p><a class="btn" href="<?=BASE_URL?>/teacher/courses.php">My courses</a></div><div class="card"><h2>Upcoming deadlines</h2><?php if(!$deadlines->num_rows):?><p class="muted">No upcoming deadlines.</p><?php else: while($deadline=$deadlines->fetch_assoc()):?><p><b><?=e($deadline['title'])?></b><br><span class="muted"><?=e($deadline['subject_code']?:$deadline['course_title'])?> · <?=e($deadline['due_date'])?></span></p><?php endwhile; endif;?></div><?php else:?><div class="card"><h2>Your classes</h2><p>View announcements, download learning materials, and submit assignments.</p><a class="btn" href="<?=BASE_URL?>/student/courses.php">My classes</a></div><?php endif;?><?php include __DIR__.'/includes/footer.php';?>
